import{_ as o,o as e,c as a,a2 as n}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"连接器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/connectors.md","filePath":"zh/guides/connectors.md","lastUpdated":1788855895000}'),r={name:"zh/guides/connectors.md"};function s(i,t,h,l,d,c){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="连接器" tabindex="-1">连接器 <a class="header-anchor" href="#连接器" aria-label="Permalink to &quot;连接器&quot;">​</a></h1><p>连接器让 Bot 能用上第三方服务（GitHub、Notion 这类）。在应用市场里挑一个服务，走 OAuth 授权或者填 API Key，绑到某个 Bot 上——之后对话里 Bot 就能直接调这个服务的工具。</p><p>背后接的是 <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a>，一个和 Memoh 一起部署的配套服务。所有凭据（OAuth token、API Key）都存在 Connect-It 那边；Memoh 只存一张绑定表——哪个 Bot 绑了哪个连接、工具命名空间叫什么、开没开。</p><hr><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><p>服务端配置了 Connect-It 地址，连接器功能才会出现：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 例如 &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 服务端之间的可信 token</span></span></code></pre></div><p>两项留空即关闭该功能。线上环境建议用对应的环境变量（<code>MEMOH_CONNECT_IT_BASE_URL</code>、<code>MEMOH_CONNECT_IT_API_TOKEN</code>）。</p><p>一键 Server Deploy 会在全新安装时自动带起一个同机部署的 Connect-It，见 <a href="/zh/self-hosted/docker.html#connect-it-连接器">Server Deploy</a>。没配置 Connect-It 时，应用市场不会显示 <strong>Connectors</strong> tab，连接器相关操作会提示服务器未配置连接器。</p><hr><h2 id="连接一个服务" tabindex="-1">连接一个服务 <a class="header-anchor" href="#连接一个服务" aria-label="Permalink to &quot;连接一个服务&quot;">​</a></h2><ol><li>在 Web UI 中打开 <strong>Supermarket</strong>。</li><li>停在 <strong>Connectors</strong> tab——配置了连接器时它排在第一个，也是默认落地的 tab。</li><li>选一个连接器，点 <strong>Connect</strong>。</li><li>选择目标 Bot。</li><li>选认证方式——OAuth 还是 API Key，取决于这个连接器支持什么。</li><li>OAuth 走弹窗完成授权；浏览器拦了弹窗的话，给页面放行弹窗再试。API Key 则填好凭据字段。</li><li>连接会出现在该 Bot 的 <strong>Connectors</strong> tab 里。</li></ol><hr><h2 id="管理连接" tabindex="-1">管理连接 <a class="header-anchor" href="#管理连接" aria-label="Permalink to &quot;管理连接&quot;">​</a></h2><p>Bot 详情页有一个 <strong>Connectors</strong> tab，列出这个 Bot 连了哪些服务。每条连接会显示状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><strong>Connected</strong></td><td>正常，工具对 Bot 可用</td></tr><tr><td><strong>Waiting for authorization</strong></td><td>连接建了但 OAuth 没走完；补完授权，或者断开它</td></tr><tr><td><strong>Authorization required</strong></td><td>凭据过期或被撤销，点 <strong>Reauthorize</strong> 重新授权</td></tr><tr><td><strong>Authorization failed</strong></td><td>上次授权没成功，可再点 <strong>Reauthorize</strong> 重试</td></tr><tr><td><strong>Unavailable</strong></td><td>这个连接器在 Connect-It 侧已经下架</td></tr><tr><td><strong>Disabled</strong></td><td>已停用，工具不会给到 Bot</td></tr></tbody></table><p>在这个 tab 里可以：</p><ul><li><strong>启用 / 停用</strong>某条连接，不用删掉它。</li><li><strong>Reauthorize</strong> 重新授权凭据失效的连接。</li><li><strong>Disconnect</strong> 断开连接——会把绑定从 Bot 上移除，<strong>并且</strong>删掉 Connect-It 里存的这条连接（含凭据）。</li></ul><p>OAuth 授权中途放弃的话，这条连接会一直停在 <strong>Waiting for authorization</strong>，手动断开即可清理。</p><hr><h2 id="工具怎么到-bot-手上" tabindex="-1">工具怎么到 Bot 手上 <a class="header-anchor" href="#工具怎么到-bot-手上" aria-label="Permalink to &quot;工具怎么到 Bot 手上&quot;">​</a></h2><p>对话时，Memoh 会把这个 Bot 所有启用且状态正常的连接聚合成一个 MCP 会话，作为工具源给智能体。连接器工具和 workspace、MCP 工具并排出现。</p><p>每条连接在绑定那一刻会拿到一个按连接器类型生成的<strong>工具命名空间</strong>——GitHub 连接是 <code>github</code>，再连一个就是 <code>github-2</code>。命名空间在绑定的整个生命周期内固定不变：之后增删其它连接，不会影响已有连接的工具名。</p><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/guides/supermarket.html">应用市场</a> —— 发现和连接服务的入口。</li><li><a href="/zh/guides/mcp.html">MCP</a> —— 直接管理 MCP 连接。</li><li><a href="/zh/self-hosted/docker.html#connect-it-连接器">Server Deploy</a> —— 同机部署 Connect-It、凭据管理和 OAuth 回调地址。</li></ul>`,26)])])}const u=o(r,[["render",s]]);export{g as __pageData,u as default};
